/**
 * Cards organize and present similiar content that users can scan quickly and interact with. They always show relevant content and actionable information. They contain text, images, icons and buttons placed with hierarchy, and may be placed as a series or feed of similar content.
 *
 * - {@link https://livingdesign.walmart.com/components/card/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/card/react/ React documentation}
 *
 * ### Content
 *
 * The Card accepts content as sub-components through a required `children` prop.
 *
 * Sub-components:
 *  1. Card Actions (optional)
 *  1. Card Content (required)
 *  1. Card Header (optional)
 *  1. Card Media (optional)
 *
 * ### Size
 *
 * The Card comes in two sizes `small` (default) and `large` which can be set through the optional `size` prop.
 *
 * ```tsx
 * <Card size="small">{...}</Card>
 * ```
 *
 * ### Example
 *
 * ```tsx
 * import * as React from "react";
 * import {
 *   Button,
 *   ButtonGroup,
 *   Card,
 *   CardActions,
 *   CardContent,
 *   CardHeader,
 *   CardMedia
 * } from "@walmart-web/livingdesign-components";
 * import Icon from "@livingdesign/icons";
 *
 * export default () => {
 *   return (
 *     <Card size="small">
 *       <React.Fragment>
 *         <CardMedia>
 *           <img
 *             alt="A placeholder kitten"
 *             src="https://placekitten.com/g/200/200"
 *             width="100%"
 *             height="300px"
 *           />
 *         </CardMedia>
 *         <CardHeader
 *           leadingIcon={<Icon.WalmartPlus size="large" />}
 *           title="Welcome"
 *           trailing={
 *             <Button variant="tertiary">Start Here</Button>
 *           }
 *         />
 *         <CardContent>
 *           Lorem ipsum dolor sit amet, consectetur
 *           adipiscing elit.
 *         </CardContent>
 *         <CardActions>
 *           <ButtonGroup>
 *             <Button variant="tertiary">Action1</Button>
 *             <Button variant="primary">Action2</Button>
 *           </ButtonGroup>
 *         </CardActions>
 *       </React.Fragment>
 *     </Card>
 *   );
 * }
 * ```
 */
export declare const Card: React.FunctionComponent<CardProps>;
